"import { chromium } from "@playwright/test";

async function main() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const testEmail = `playwright_${Date.now()}@teste.com`;
  console.log("1. Acessando http://localhost:3000/cadastro...");
  await page.goto("http://localhost:3000/cadastro", { waitUntil: "networkidle" });

  console.log("2. Preenchendo campos...");
  await page.locator('input[name="nome"]').fill("Leonardo Playwright");
  await page.locator('input[name="email"]').fill(testEmail);
  await page.locator('input[name="senha"]').fill("SenhaSegura@123");
  await page.locator('input[name="confirmacao"]').fill("SenhaSegura@123");

  console.log("3. Clicando em 'Criar conta'...");
  await page.locator('button[type="submit"]').click();

  console.log("4. Aguardando resposta...");
  await page.waitForTimeout(5000);

  const urlAtual = page.url();
  console.log("URL Atual:", urlAtual);

  const erroElem = page.locator('text=Não foi possível');
  const temErro = await erroElem.isVisible().catch(() => false);

  if (temErro) {
    console.error("FALHA: Mensagem de erro continua visível na página!");
    const msg = await erroElem.textContent();
    console.error("Mensagem exibida:", msg);
  } else if (urlAtual.includes("/onboarding")) {
    console.log("✅ SUCESSO TOTAL: Cadastro realizado e redirecionado para /onboarding!");
  } else {
    console.log("Página atual:", await page.title());
  }

  await browser.close();
}

main().catch(console.error);
"

